-- 2252 🏋️ Exercises from the book "coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-defending" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-defending');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Back three shifts to ball position', 'defending', 'unopposed', 'out_of_possession', 24, 25, 'Defending Against 1 Forward - Session Practice 1', 'Conte (Juventus)', 'The three centre backs learn to position themselves as a unit relative to where the ball is.', 'Half pitch with goal and GK; three centre backs in front of goal; four opposition midfielders on red cones across the halfway line with spare balls.', 'The four midfielders move the ball between themselves while the back three shift, mainly sideways, to match each ball position. In the progression the midfielders then play into one centre back, who holds briefly while the other two move in and back to cover as if he were contesting an opponent, then he returns it to a midfielder.', NULL, 'Midfielders pass into a centre back; the other two react with cover as though he had an opponent to press.', 'Learn cover and balance; tightly synchronised movement among the three; read each situation from where the pass goes.', '3 CB + GK + 4 midfielders', 8, 8, 'half pitch', NULL, NULL, NULL, true, true, false, NULL, 10),
  ('Back three v one forward: pressure-cover-balance', 'defending', 'passive', 'out_of_possession', 26, 26, 'Defending Against 1 Forward - Session Practice 2', 'Conte (Juventus)', 'Shift with the ball and mark a lone centre forward using pressure, cover and balance.', 'As practice 1 (half pitch, GK, back three, four midfielders on cones) plus one opposition forward between the centre backs.', 'Midfielders circulate; when one plays into the forward, the nearest centre back presses the ball and the other two drop into cover. The forward holds a couple of seconds, plays back and moves for the next pass; midfielders may also play in behind a wide centre back to test immediate cover.', 'Forward holds the ball a couple of seconds then returns it; no scoring.', NULL, 'Mark the forward according to his position, the ball, the goal and teammates'' positions.', '3 CB + GK v 1 forward + 4 midfielders', 9, 9, 'half pitch', NULL, NULL, NULL, true, true, false, NULL, 20),
  ('Back three drop or push up', 'defending', 'opposed', 'out_of_possession', 27, 28, 'Defending Against 1 Forward - Session Practice 3', 'Conte (Juventus)', 'Recognise open versus closed ball situations and drop off or step up together.', 'Half pitch with GK and back three; four opposition midfielders on red cones near halfway.', 'Midfielders pass among themselves; at a chosen moment one carries the ball forward 8-10 yards and then either tries a ball in behind, stops and plays back, or keeps driving and looks for a through pass. The back three (with the GK) drop or step up as one according to the situation.', NULL, 'Add one, then two opposition forwards who run in behind to receive and score.', 'Read the situation and synchronise to stay compact; GK moves up and back with the line; constant talk between defenders.', '3 CB + GK v 4 midfielders (+1-2 forwards)', 8, 10, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Open ball defending in four zones', 'defending', 'opposed', 'out_of_possession', 29, 29, 'Defending Against 1 Forward - Session Practice 4', 'Conte (Juventus)', 'Defend an open ball situation with vertical shifts of the back line and midfield support.', 'Half pitch split into zones: high zone (about double the penalty area) with back three + GK v one forward; a narrow blue zone with the holding midfielder; a low red zone with four opposition midfielders v two attacking midfielders; coach with balls behind.', 'Coach feeds a midfielder in the red zone; the 4v2 aims to get someone free or carrying forward to create an open ball and then attack the goal. The back line drops to stop passes in behind; once the ball leaves the red zone the holding midfielder closes it down; a pass back to the red zone (closed ball) triggers the line to step up together.', 'Only the ball carrier may leave the red zone; the two defending attacking midfielders must stay in the red zone.', 'Add a second forward in the high zone (3v2 instead of 3v1).', NULL, '5 v 6 + GK', 12, 13, 'half pitch in 4 zones', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Offside trap to fix bad positioning', 'defending', 'opposed', 'out_of_possession', 40, 40, 'Defending Against 2 Forwards - Session Practice 1', 'Conte (Juventus)', 'Train the middle centre back to judge when to step up and catch a forward offside after the line was badly set.', 'Half of a full pitch: blue zone across the pitch holding the left and right centre backs; middle centre back and one forward deeper, outside the zone; white zone near halfway with four midfielders on red cones; coach on the side.', 'Midfielders pass and the back three shift with the ball while the middle centre back marks the forward. When a midfielder enters the white zone with the ball the forward offers to feet or runs in behind; the middle centre back either steps into the blue zone to leave him offside or tracks his run if the timing is wrong. Coach judges the decision.', 'Midfielders must pass forward from the white zone.', NULL, 'Focus on the deeper middle centre back''s judgement; reading the moment (ball carrier''s head down, heavy touch) is the key.', '3 CB + GK v 1 forward + 4 midfielders', 9, 9, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Back three v two forwards', 'defending', 'passive', 'out_of_possession', 41, 41, 'Defending Against 2 Forwards - Session Practice 2', 'Conte (Juventus)', 'Move as a unit with the ball and mark two forwards with pressure, cover and balance.', 'Half pitch with GK, back three and two opposition forwards; four midfielders on red cones near halfway.', 'Midfielders circulate until one plays into a forward; the back three shift (mainly sideways) with the ball, the defender on the receiver presses and the other two give cover and balance. The receiver holds a couple of seconds, plays back and both forwards move again; midfielders may also play in behind a wide centre back for a forward to run onto.', 'Receiver holds a couple of seconds then returns the ball.', NULL, 'Position from the ball and mark opponents; cover and balance through synchronised movement.', '3 CB + GK v 2 forwards + 4 midfielders', 10, 10, 'half pitch', NULL, NULL, NULL, true, true, false, NULL, 60),
  ('When to track a dropping forward', 'defending', 'passive', 'out_of_possession', 42, 43, 'Defending Against 2 Forwards - Session Practice 3', 'Conte (Juventus)', 'Decide the right moment to follow a forward who drops deep when the back three are well positioned.', 'Half pitch with GK; two zones each 10 yards deep across the pitch width in front of the defence, blue (nearer goal) and red (deeper); back three and two forwards start outside the zones; four midfielders on red cones.', 'Midfielders pass while forwards move constantly. Defenders always follow a forward dropping into the blue zone; if he drops further into the red zone they decide whether to go with him. Receiver holds briefly, plays back and both reset outside the zones.', 'Receiver holds a couple of seconds then plays back.', NULL, 'Middle centre back calls ''stay'' or ''go''; timing of the step is everything; forwards check away before showing.', '3 CB + GK v 2 forwards + 4 midfielders', 10, 10, 'half pitch, zones 10 yards x pitch width', NULL, NULL, NULL, true, true, false, NULL, 70),
  ('Tracking forwards with an unbalanced line', 'defending', 'passive', 'out_of_possession', 44, 45, 'Defending Against 2 Forwards - Session Practice 4', 'Conte (Juventus)', 'Choose aggressive marking or playing for time when the outside centre backs are caught too high.', 'As practice 3 but the left and right centre backs and one forward start inside the blue zone; middle centre back behind the zones; second forward free to roam; four midfielders on cones.', 'Forwards receive in the blue zone or drop into the red zone when they choose; receiver holds, plays back and moves again. Example reactions: a central pass outside the zones makes both outside backs drop to cover the middle; a wider pass to a dropping forward lets the near back press while the middle one covers and the far one balances.', 'Outside centre backs may not leave the blue zone until a pass goes to a forward.', NULL, 'Know when to mark aggressively and when to delay; move in sync to give cover and balance; defenders coach each other.', '3 CB + GK v 2 forwards + 4 midfielders', 10, 10, 'half pitch, zones 10 yards x pitch width', NULL, NULL, NULL, true, true, false, NULL, 80),
  ('Weak-side wing back makes a back four', 'defending', 'passive', 'out_of_possession', 54, 55, 'Defending Against 3 Forwards - Session Practice 1', 'Conte (Juventus)', 'Defend three narrow forwards with the weak-side wing back well placed so the ball-side defender can press hard.', 'Half pitch split into two halves lengthways; GK, back three and both wing backs v three narrow forwards; four opposition midfielders on red cones (two wide, two central); coach on the side.', 'Midfielders circulate; the back three shift and mark the forwards while the weak-side wing back stays level with the far forward. Version 1: only wide players may pass into the forwards, and the ball-side wing back presses the wide man without blocking the pass. Version 2: only the central midfielders may play in. On a pass to a forward the nearest centre back presses and the rest provide cover, balance and the extra man; receiver holds and plays back.', 'Forward holds a couple of seconds then returns the ball; coach corrects positioning.', NULL, NULL, '3 CB + 2 WB + GK v 3 forwards + 4 midfielders', 13, 13, 'half pitch', NULL, NULL, NULL, true, true, false, NULL, 90),
  ('Back three plus wing back v three forwards live', 'defending', 'opposed', 'out_of_possession', 56, 57, 'Defending Against 3 Forwards - Session Practice 2', 'Conte (Juventus)', 'Win the ball aggressively against three forwards when the weak-side wing back is well positioned.', 'Same as practice 1 (half pitch, GK, back three + two wing backs v three forwards, four midfielders on cones, coach).', 'Once a midfielder plays into a forward, the three forwards have 10 seconds to attack and score. Defenders mark tightly to win it, clear to the midfielders and then step up together. Run both versions: passes in only from the wide players, or only from the central midfielders.', 'Forwards must score within 10 seconds; only the three forwards join the attack.', NULL, 'Keep moving to the right spots; one centre back presses while the others cover, balance and keep the extra man.', '6 (3 CB + 2 WB + GK) v 3 forwards + 4 midfielders', 13, 13, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Delay until weak-side wing back recovers', 'defending', 'passive', 'out_of_possession', 58, 59, 'Defending Against 3 Forwards - Session Practice 3', 'Conte (Juventus)', 'Defend three forwards when the weak-side wing back is out of position: delay first, press once he recovers.', 'Half pitch in two halves; back three + GK v three forwards; weak-side wing back starts in a 5 x 5 yard red box out wide (one box each side); four opposition midfielders on cones; coach.', 'Midfielders circulate and the back three shift and mark. Version 1: passes in only from the wide players; the ball-side wing back presses the wide man without blocking the pass, and the defender nearest the receiving forward contests passively until the wing back has recovered, then switches to aggressive. Version 2: passes in only from the central midfielders. Receiver holds 2-6 seconds then plays back.', 'Whites do not try to score; weak-side wing back always starts in the 5 x 5 box.', NULL, 'Communication so the first defender knows when to stop delaying and win the ball.', '3 CB + 2 WB + GK v 3 forwards + 4 midfielders', 13, 13, 'half pitch, 5 x 5 yard boxes', NULL, NULL, NULL, true, true, false, NULL, 110),
  ('Passive then aggressive v three forwards', 'defending', 'opposed', 'out_of_possession', 60, 60, 'Defending Against 3 Forwards - Session Practice 4', 'Conte (Juventus)', 'Switch from delaying to aggressive defending against three forwards once the weak-side wing back is back in position.', 'Same as practice 3: back three + GK v three forwards, wing backs starting in 5 x 5 boxes wide, four opposition midfielders on cones, coach.', 'From the diagrams: a pass into a forward is met passively to stop him turning; once the wing back recovers the ball-side defender switches to aggressive pressure. Shown with passes from wide and from central midfielders.', NULL, NULL, NULL, '3 CB + 2 WB + GK v 3 forwards + 4 midfielders', 13, 13, 'half pitch, 5 x 5 yard boxes', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Midfield three block through balls', 'defending', 'opposed', 'out_of_possession', 68, 68, 'Session (Midfield Positioning): Practice 1', 'Conte (Juventus)', 'The midfield three learn to shift as a compact unit and cut out through passes played by opposition defenders.', 'A blue zone 10 yards deep across the pitch width holds 3 or 4 white defenders; a red zone 5 x 44 yards further down holds 2 white forwards; 3 black midfielders stand between the zones in front of the red zone.', 'The white defenders move the ball across and pick a moment to slip a through pass to a forward in the red zone. The black midfielders slide with the ball, keep their shape and narrow the lanes to intercept.', 'A pass only counts if received inside the red zone; midfielders may not enter the red or blue zones.', NULL, 'Talk constantly to keep short distances; read the ball''s travel time and react early to intercept.', '3 or 4 defenders + 2 forwards v 3 midfielders', 8, 9, 'blue zone 10 yards x pitch width; red zone 5 x 44 yards', NULL, NULL, NULL, false, false, true, NULL, 130),
  ('Midfield safe distance v through balls', 'defending', 'opposed', 'out_of_possession', 69, 69, 'Session (Midfield Positioning): Practice 2', 'Conte (Juventus)', 'Midfielders hold a safe distance from the ball-playing defenders and keep shape to block through passes.', 'Larger zones than practice 1: blue zone 15 yards x pitch width with 4 white defenders, red zone 15 x 44 yards holding the 3 black midfielders and 2 white forwards who stay behind them.', 'White defenders step in or out with the ball and look for a through pass. The black midfielders drop or step to keep their distance and compactness; the white forwards must stay behind them and drop when they drop.', 'White forwards must always stay goal-side of the black midfielders.', NULL, 'Stay compact, move together, keep enough distance to have time to react to the pass.', '4 defenders + 2 forwards v 3 midfielders', 9, 9, 'blue zone 15 yards x pitch width; red zone 15 x 44 yards', NULL, NULL, NULL, false, false, true, NULL, 140),
  ('3v3 midfield pressure cover balance', 'defending', 'opposed', 'out_of_possession', 71, 71, 'Session (Defending Opposition Midfielders): Practice 1', 'Conte (Juventus)', 'Defend the central zone 3v3 using pressure, cover and balance.', '20 x 44 yard area with a red end line at each end; 3 black midfielders against 3 white midfielders.', 'Whites try to dribble over the red line; the nearest black presses and the other two cover and balance, staying compact. If blacks win it they have 5 seconds to dribble over the opposite line.', 'Score by dribbling over the end line; after a score or ball out, restart from the starting positions; 5 seconds to counter after a win.', NULL, 'One presser, organised and talking; keep short distances and react together when a dribbler tries to split you.', '3v3', 6, 6, '20 x 44 yards', 18.3, 40.2, NULL, false, false, true, NULL, 150),
  ('3v3 midfield end zone game', 'small_sided_game', 'opposed', 'out_of_possession', 72, 72, 'Session (Defending Opposition Midfielders): Practice 2', 'Conte (Juventus)', 'Same 3v3 pressure-cover-balance defending, now with end zones and mini goals to finish into.', 'The 20 x 44 yard central area plus a 5 x 44 yard end zone at each end, with 3 mini goals behind each end zone.', 'Play 3v3; the nearest defender presses while the other two cover and balance. Dribbling over the red line into the end zone earns a point, and a shot into a mini goal earns a bonus point. Blacks winning it have 5 seconds to break out.', 'Must shoot immediately on entering the end zone (first touch inside it); restart from the starting positions after a point or ball out.', NULL, 'Compact shape, one presser, cover and balance from the other two.', '3v3', 6, 6, '20 x 44 yards + two 5 x 44 yard end zones', 27.4, 40.2, NULL, true, false, true, NULL, 160),
  ('Rear block v 3-4-3 functional', 'phase_of_play', 'opposed', 'out_of_possession', 79, 79, 'Practice for this tactical situation (v 3-4-3)', 'Conte (Juventus)', 'The 3-5 rear block defends against a 4-3 front with pressure, cover, double marking and blocking through balls.', 'Half pitch with a goal and GK; black team of 3 defenders and 5 midfielders against 4 white midfielders and 3 forwards, plus 2 white feeders (No.4, No.5) at halfway; 2 mini goals on the halfway line.', 'Whites, helped by the feeders, build and try to score. Blacks block through passes and double up; once they win it they must score in a mini goal within 6-8 seconds.', '6-8 seconds to score in a mini goal after winning the ball.', 'Can be set up against other formations.', 'Position by the ball; nearest player presses, others cover and balance with communication; back 3 + midfield 5 stay compact and move in sync.', 'GK + 8 v 7 + 2 feeders', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Holding midfielder reads equal numbers', 'defending', 'opposed', 'out_of_possession', 84, 84, 'Session (v 3-4-1-2): Practice 1', 'Conte (Juventus)', 'The defensive midfielder learns when to drop to cover a back line left level in numbers against a 3-4-1-2.', 'A white line across the pitch and two 5 x 44 yard zones (blue behind red); white No.10 and the black holding midfielder (21) start in the red zone, other black midfielders and wing backs outside; 4 white passers on red cones.', 'Whites circulate and No.10 roams between both zones. If No.10 is in the blue zone and the weak-side wing back is beyond the white line, No.21 drops into the blue zone; otherwise he holds in the red zone. Other midfielders press, cover and balance.', NULL, NULL, 'Drop at the right moment after reading No.10 and the weak-side wing back; others position by the ball.', '5 whites v 5 blacks', 10, 10, 'two 5 x 44 yard zones', NULL, NULL, NULL, false, false, false, NULL, 180),
  ('Equal numbers at back v 3-4-1-2', 'defending', 'opposed', 'out_of_possession', 85, 86, 'Session (v 3-4-1-2): Practice 2', 'Conte (Juventus)', 'Compensate for equal numbers at the back by reading the situation, now with live defenders and forwards.', 'As practice 1 plus 3 black defenders and 2 white forwards inside a larger blue zone, with a yellow end zone behind it and a red zone in front.', 'White midfielders pass and then feed a forward; No.10 roams both zones. Whites try to dribble over the red line or receive in the yellow zone. No.21 drops or holds depending on the weak-side wing back; blacks win it, clear to the white midfielders and step up together.', 'Offside applies; after the forward pass No.10 and No.21 may not enter the blue zone; other centre mids position but do not block passes; weak-side wing back may join the blue zone only if he started behind the white line.', 'Add a GK; whites finish unopposed after beating the red line or receiving in the end zone.', 'A wrong decision by No.21 leaves 3v3 at the back; step up together after the clearance.', '7 whites v 8 blacks', 15, 16, NULL, NULL, NULL, NULL, false, false, true, NULL, 190),
  ('Rear block v 3-4-1-2 functional', 'phase_of_play', 'opposed', 'out_of_possession', 87, 87, 'Session (v 3-4-1-2): Practice 3', 'Conte (Juventus)', 'Defend as a 3-5 block: position by the ball, press, cover and balance, stay compact and synchronised.', 'Half pitch with a goal and GK; black 3 defenders + 5 midfielders against a white 4-1-2 plus 2 outside feeders; 2 mini goals on halfway.', 'Whites attack with the feeders'' help; blacks block through passes, double mark and win the ball, then counter into a mini goal within 6-8 seconds.', '6-8 seconds to score after winning the ball.', 'Adjust to defend against any formation.', NULL, 'GK + 8 v 7 + 2 feeders', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Cone signal: who closes full back', 'defending', 'opposed', 'out_of_possession', 97, 98, 'Session (v 4-2-3-1): Practice 1', 'Conte (Juventus)', 'Midfielders recognise who presses the full back and who drops so the back line keeps a spare man against a 4-2-3-1.', 'A yellow zone (2 x 44 yards) for white No.10 and a blue zone (5 x 44) behind the black midfield; white full backs each hold a yellow and a blue cone; black wing backs in yellow bibs, attacking mids in blue bibs.', 'Whites pass along the red cones; when a full back receives he lifts a cone. Yellow: the wing back closes him and a midfielder (by No.10''s spot) drops into the blue zone. Blue: an attacking midfielder presses, nobody drops, and the rest shift to the strong side.', NULL, NULL, 'Midfielders keep telling each other where No.10 is; drop at the right moment when the wing back goes.', '6 whites v 5 blacks', 11, 11, 'yellow zone 2 x 44 yards; blue zone 5 x 44 yards', NULL, NULL, NULL, false, false, false, NULL, 210),
  ('Closing full back keeps 3v2 v 4-2-3-1', 'defending', 'opposed', 'out_of_possession', 99, 99, 'Session (v 4-2-3-1): Practice 2', 'Conte (Juventus)', 'Keep a numerical edge at the back when the wing back steps out, now with live defenders and a forward.', 'Add 2 black defenders and a white forward in a 10 x 44 yard blue zone, a yellow end zone behind and a red zone in front where No.10 sits.', 'Whites pass round then feed No.10 or the forward; they aim to dribble over the red line or receive in the yellow zone. The holding mid or weak-side attacking mid drops into the red zone to make 3v2; blacks win it, clear and step up together.', 'Only wing backs close the ball-carrying full back; black midfielders do not block through passes; defenders may not enter the yellow zone; offside applies.', 'Add a GK; whites finish unopposed after beating the line or receiving in the yellow zone.', NULL, '7 whites v 7 blacks', 14, 15, 'blue zone 10 x 44 yards', NULL, NULL, NULL, false, false, true, NULL, 220),
  ('Cone signal press v 4-4-2', 'defending', 'opposed', 'out_of_possession', 104, 105, 'Practice for this tactical situation (v 4-4-2, variation)', 'Conte (Juventus)', 'Midfielders synchronise so equality at the back is avoided when defending a 4-4-2.', 'Variation of the 4-2-3-1 cone practice with no white player behind the midfield; white midfielders and full backs on red cones, a blue zone behind the black midfield.', 'When a white full back receives he lifts a cone: yellow means the wing back closes and the holding midfielder (21) drops into the blue zone; blue means the attacking midfielder closes and 21 stays out.', NULL, NULL, NULL, '4 whites v 5 blacks', 9, 9, NULL, NULL, NULL, NULL, false, false, false, NULL, 230),
  ('Wing back reads No.10 v 4-3-1-2', 'defending', 'opposed', 'out_of_possession', 110, 111, 'Session (v 4-3-1-2): Practice 1', 'Conte (Juventus)', 'Players coach each other into the right moves to stop equal numbers at the back against a 4-3-1-2.', 'White No.10 stays inside a 5 x 44 yard blue zone; black left wing back advanced on a yellow cone, right wing back deeper; white full backs and midfielders on red cones.', 'Whites pass while blacks shift. Ball to the right back: the left wing back always presses. Ball to the left back: either the right wing back or the attacking midfielder presses, depending on where the left wing back is, with the right wing back dropping into the blue zone when needed.', NULL, NULL, 'Talk to teammates to trigger the right action; compensate for No.10''s advanced spot.', '6 whites v 5 blacks', 11, 11, 'blue zone 5 x 44 yards', NULL, NULL, NULL, false, false, false, NULL, 240),
  ('Wing back drops for 4v3 v 4-3-1-2', 'defending', 'opposed', 'out_of_possession', 112, 113, 'Session (v 4-3-1-2): Practice 2', 'Conte (Juventus)', 'The far wing back judges when to drop in to keep 4v3 at the back against a 4-3-1-2.', 'As practice 1 plus 3 black defenders and 2 white forwards inside the blue zone, a yellow end zone behind it and a red zone in front.', 'Whites pass and feed a forward; No.10 roams both zones. Whites try to dribble over the end line or receive in the yellow zone. Black wing backs enter zones when right; the right wing back drops level with No.10 or covers a centre back who steps out. Blacks win it, clear and step up.', 'Offside applies; black centre mids position but do not block through passes.', 'Add a GK; whites finish unopposed after beating the end line or receiving in the yellow zone.', 'Position by the ball; right wing back drops at the right moment; whole unit stays compact and in sync.', '8 whites v 8 blacks', 16, 17, NULL, NULL, NULL, NULL, false, false, true, NULL, 250),
  ('Cone signal press v 4-3-3', 'defending', 'opposed', 'out_of_possession', 119, 120, 'Session (v 4-3-3): Practice 1', 'Conte (Juventus)', 'Keep a numerical edge in the back zone when pressing the full backs or holding midfielder of a 4-3-3.', 'White 2 full backs and 3 midfielders (6, 8, 10) against black midfielders 23, 21, 8 and wing backs 26, 22; a blue zone across the pitch behind the black midfield; full backs hold yellow and blue cones.', 'Whites pass along the red cones while 8 and 10 drift in and out of the blue zone. Yellow cone: the wing back presses the full back; blue cone: the attacking midfielder presses; ball to No.6: black 21 presses. Whoever steps out, someone drops so the blue zone stays outnumbered.', 'If both white attacking mids enter the blue zone, blacks must make 3v2 there.', 'Continues on p121 (practice 2, outside this range).', NULL, '5 whites v 5 blacks', 10, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 260),
  ('Hold numbers closing full back vs 4-3-3 with forwards', 'defending', 'opposed', 'out_of_possession', 121, 121, 'Defending With the Rear Block Against the 4-3-3: Practice 2', 'Conte (Juventus)', 'Rear block keeps an extra man at the back while one player steps out to press the full back against a 4-3-3.', 'Middle-third zones: red midfield zone, blue zone for the back line and a yellow end zone in front of goal. Whites have 2 full backs, holding mid 6, two attacking mids and 3 forwards in the blue zone; blacks have 3 midfielders, 2 wing backs and 3 centre backs.', 'Whites circulate across the back and pick a moment to pass into a forward, aiming to dribble over the red end line or receive a through ball in the yellow zone. White attacking mids roam into the red zone for 4v4; a black midfielder drops in to restore the overload. Blacks win it, clear and step up together.', 'Black midfielders hold position but do not block through passes; after the first pass to a forward no more whites may enter the red or blue zone; defenders may not go beyond the red end line; offside applies.', 'Add a goalkeeper; whites finish unopposed after dribbling over the end line or receiving in the yellow zone.', 'Step up together after a clearance; one midfielder drops to keep superiority.', '8v8 (+GK in progression)', 16, 17, NULL, NULL, NULL, NULL, false, false, true, NULL, 270),
  ('Forwards block passes into midfield vs back three', 'defending', 'overload', 'out_of_possession', 136, 136, 'Session (5 Practices): Practice 1', 'Conte (Juventus)', 'Two forwards defend passively and screen passes from a back three into central midfield.', 'Blue zone 10 x 50 yards for 3 white defenders (GK behind) and a red zone 10 x 35 yards behind it holding 2 white central mids and 1 black holding mid; 2 black forwards between the zones.', 'GK feeds the back three who pass among themselves looking to find a white midfielder in the red zone; the mids then try to dribble over the red end line via a combination or a 1v1. Black forwards stay compact near their holding mid, keep shape and block lanes.', 'If blacks win it they counter and must score within 6-8 seconds, 3v3 (holding mid joins, white mids do not defend).', NULL, 'Forwards position off the ball; when one presses the carrier the other drops to cover.', '6+GK v 3', 10, 10, 'blue zone 10 x 50 yards; red zone 10 x 35 yards', 9.1, 45.7, NULL, false, true, true, NULL, 280),
  ('Force the ball wide vs back three zonal', 'defending', 'opposed', 'out_of_possession', 137, 137, 'Session (5 Practices): Practice 2 (variation)', 'Conte (Juventus)', 'Press a three-man defence high and steer the ball out to the flank.', 'Three zones across the width: a central red zone and two blue side zones. Two black forwards start on yellow cones in the red zone, black attacking mids 8 and 23 wait outside each blue zone; 3 white defenders start one per zone with the GK behind; a coach waits beyond.', 'GK plays to a centre back; whites try to dribble over the red end line, wide defenders can run diagonally into the red zone for a through ball. Forwards press to push the ball into a blue zone; if the wide defender stays there over 4 seconds the strong-side attacking mid enters to double mark.', 'Whites may move across all zones; on a regain blacks counter to score within 6 seconds, 3v3.', 'See Practice 3: add a white holding mid.', 'The pressing forward cuts off the back pass across the pitch so the ball goes wide.', '3+GK v 4', 8, 9, NULL, NULL, NULL, NULL, false, true, true, NULL, 290),
  ('Force wide vs back three plus holding mid', 'defending', 'opposed', 'out_of_possession', 138, 138, 'Session (5 Practices): Practice 3 (progression)', 'Conte (Juventus)', 'High press on a back three supported by a holding midfielder.', 'As Practice 2 (central red zone, two blue side zones) plus a white defensive mid starting on a red cone below the red zone.', 'The white DM enters the red zone once the CB or GK passes left or right. The most advanced forward reads it and reacts; whites still try to dribble over the red line, now also using the DM. Forwards force it wide, press to win and counter.', 'Attacking mid joins after the ball is in a blue zone for 4 seconds; counter must score within 6 seconds.', NULL, 'Main aim is still forcing it wide; when one forward presses the carrier the other blocks the passing options.', '4+GK v 4', 9, 10, NULL, NULL, NULL, NULL, false, true, true, NULL, 300),
  ('Front block press stops switch 7v7', 'defending', 'opposed', 'out_of_possession', 139, 140, 'Session (5 Practices): Practice 4 (progression)', 'Conte (Juventus)', 'Press a back three as a front block, create a strong side and stop the switch.', 'Half a pitch split down the middle; white GK and penalty area; 8 x 8 yard boxes near each touchline as switch targets. Whites play 3-4 (or 3-5 with a centre mid); blacks start on yellow cones.', 'From the GK pass whites score a point for 5 straight passes, dribbling over the halfway line, or a switch received in a weak-side 8 x 8 box (several per move allowed). Blacks press, win it and score within 6-8 seconds; a lost counter or ball out restarts with the white GK.', 'Whites may not switch via a pass into the penalty area; switch counts only if received inside a far box; boxes are not in play for the GK''s first pass.', NULL, 'Make a strong side and push play to the touchline; mark receivers aggressively; double mark when possible and stay compact.', '7v7 (+GK)', 15, 16, 'half pitch; 8 x 8 yard boxes', NULL, NULL, NULL, false, true, true, NULL, 310),
  ('Passive block vs back three zonal 7v9', 'defending', 'overload', 'out_of_possession', 141, 142, 'Session (5 Practices): Practice 5 (progression)', 'Conte (Juventus)', 'Defend passively in the middle third against a back three and screen passes through the centre.', '2/3 of a pitch: blue zone 25 yards x full width with whites'' 3 defenders and 4 midfielders and blacks'' 2 wing backs, 3 mids and 2 forwards; a red zone 15 x 44 yards behind holding 2 white forwards; GK starts.', 'GK passes to a centre back. Whites score with a pass into a forward in the red zone, dribbling through the yellow cone gates, or a point for 2-3 straight passes in the blue zone (by level). Blacks wait for whites to enter the blue zone, block, win it and score within 6-8 seconds.', 'Blacks stay in the blue zone while defending; white forwards never leave the red zone; a lost counter or ball out restarts from the white GK.', NULL, 'Position to the ball, move together, stay compact to shut lanes to the forwards; focus is the zonal defending, not the transition. Set-up suits 3-4-1-2, 3-4-3 or 3-5-2 opponents.', '9+GK v 7', 17, 17, 'blue zone 25 yards x full width; red zone 15 x 44 yards', 22.9, NULL, NULL, false, true, true, NULL, 320),
  ('Block passes into midfield vs back four 3v6', 'defending', 'overload', 'out_of_possession', 147, 147, 'Session (2 Practices): Practice 1', 'Conte (Juventus)', 'Front two plus holding mid screen passes from a back four into midfield.', 'Blue zone 10 yards x pitch width with 4 white defenders and GK; red zone 10 x 35 yards with 2 white mids and black holding mid 21; 2 black forwards outside it.', 'GK plays in, the back four move it waiting to pass into a white mid, who then tries to dribble over the red end line via a combination or a 1v1. Black forwards stay close to their holding mid and keep shape to block.', 'On a regain blacks attack and score within 6-8 seconds, 3v4 with the holding mid joining.', 'Practice 2 widens it to 7v9.', NULL, '6+GK v 3', 10, 10, 'blue zone 10 yards x pitch width; red zone 10 x 35 yards', 9.1, NULL, NULL, false, true, true, NULL, 330),
  ('Passive block vs back four zonal 7v9', 'defending', 'overload', 'out_of_possession', 148, 149, 'Session (2 Practices): Practice 2 (progression)', 'Conte (Juventus)', 'Middle-third passive defending against a four-man back line, blocking lanes to the forwards.', '2/3 of a pitch: blue zone 25 yards x full width with whites'' 4 defenders and 3 mids against blacks'' 2 wing backs, 3 mids and 2 forwards; red zone 15 x 44 yards behind with 2 white forwards; GK starts.', 'GK to a centre back; whites score by passing into the red zone forwards, dribbling through yellow cone gates, or a point for 2-3 straight passes in the blue zone. Blacks wait for the whites to come into the zone, block, and on a win score within 6-8 seconds (7v7).', 'Blacks stay in the blue zone until they win it; white forwards stay in the red zone; lost counter or ball out restarts from the GK.', NULL, 'Position to the ball; move in sync to react; keep cohesion with small distances.', '9+GK v 7', 17, 17, 'blue zone 25 yards x full width; red zone 15 x 44 yards', 22.9, NULL, NULL, false, true, true, NULL, 340),
  ('Left flank double mark, block inside pass', 'defending', 'opposed', 'out_of_possession', 157, 158, 'Session (5 Practices): Practice 1', 'Conte (Juventus)', 'Synchronised double marking of the full back on the left while blocking the pass inside.', 'Quarter pitch plus penalty area; two 20 x 20 yard zones, the touchline one split red and yellow, the inner one blue. Players on yellow cones except white 6 (free in blue) and white 2 (free in red/yellow); GK, white CB 4, black forward 14, wing back 22, att mid 8, holding mid 21, coach.', 'GK to CB 4, forward 14 forces it towards No.2 and screens No.6. Whites score 1 for a pass to No.6, 3 for dribbling over the red end line. Who double marks depends on where No.2 receives: yellow zone = wing back plus 8; red zone = 8 presses with 14, 21 picks up No.6; coach call ''ONE'' = only the wing back closes.', 'No.2 must take at least two touches; no pass back to No.4.', 'On a regain blacks counter and must score within 6-8 seconds on the quarter pitch and box.', NULL, '4+GK v 4', 9, 10, 'quarter pitch + penalty area; two 20 x 20 yard zones', 18.3, 18.3, NULL, false, true, true, NULL, 350),
  ('Left flank double mark with extra No.10', 'defending', 'opposed', 'out_of_possession', 159, 159, 'Session (5 Practices): Practice 2 (variation)', 'Conte (Juventus)', 'Double mark on the left while also cutting off a pass into a No.10.', 'As Practice 1 plus a white No.10 standing in a small white box below the zones.', 'Blacks must stop the pass into No.10 in the box (3 points), the dribble over the red line (3 points) and the pass to No.6 (1 point).', 'No.2 at least two touches; no pass back to No.4; No.10 stays in his box and must receive there to score.', 'Counter-attack to score within 6-8 seconds after winning it.', NULL, '5+GK v 4', 10, 11, 'quarter pitch + penalty area; two 20 x 20 yard zones', 18.3, 18.3, NULL, false, true, true, NULL, 360),
  ('Right flank double mark, block inside pass', 'defending', 'opposed', 'out_of_possession', 160, 160, 'Session (5 Practices): Practice 3 (variation)', 'Conte (Juventus)', 'Mirror of the left-flank drill on the right: forward plus attacking mid double the full back.', 'Quarter pitch plus box; two 20 x 20 yard zones on the right. White GK, CB 5, left back 3, No.8 free in the blue zone; blacks forward 10, att mid 23, holding mid 21 (may enter blue), coach.', 'GK to CB 5; black 10 forces play to white 3 and screens No.8. On the pass to No.3, 10 and 23 double mark and try to win it while blocking No.8; 21 marks No.8 if he pushes up, 10 stops him if he drops. Whites: 1 for a pass to No.8, 3 for dribbling over the red line.', 'No.3 receives on the red cone then dribbles or passes with at least two touches; no pass back to No.5.', 'Counter-attack within 6-8 seconds after a regain.', NULL, '4+GK v 3', 8, 9, 'quarter pitch + penalty area; two 20 x 20 yard zones', 18.3, 18.3, NULL, false, true, true, NULL, 370),
  ('Left flank press with deep winger', 'defending', 'opposed', 'out_of_possession', 161, 162, 'Session (5 Practices): Practice 4 (variation)', 'Conte (Juventus)', 'Read whether the wing back or attacking mid presses when the opposing winger sits deep.', 'A bit more than a quarter pitch plus box; two 20 x 25 yard zones. As Practice 1 plus a white winger 7 who may enter the yellow zone or stay outside.', 'GK to CB 4. If winger 7 comes into the yellow zone, wing back 22 marks him and att mid 8 shifts to close No.2, forward 14 helps double and 21 goes into the blue zone onto No.6. If 7 stays out, 22 steps up to press with 8 doubling and 21 stays out (14 drops if No.6 comes short). Whites score 1 for a pass to No.6, 3 for dribbling over the red line.', 'No.2 at least two touches; no pass back to No.4.', 'Counter-attack within 6-8 seconds after a regain.', NULL, '5+GK v 4', 10, 11, 'two 20 x 25 yard zones', 18.3, 22.9, NULL, false, true, true, NULL, 380),
  ('Front block press vs back four functional', 'defending', 'opposed', 'out_of_possession', 163, 164, 'Session (5 Practices): Practice 5 (progression)', 'Conte (Juventus)', 'Press a four-man defence with the front block, reacting to a deep winger.', 'Half pitch in 4 sections to show strong side and high/deep full back; 4 blue 8 x 8 yard switch boxes (two per side) and 2 yellow 4 x 4 yard boxes for white wingers 7 and 11. Whites play 4-2 (or 4-1-2 with a centre mid).', 'Whites aim for 5 straight passes, dribbling over the halfway line, or a switch to a player in a weak-side blue box. Blacks press, win it and score within 6-8 seconds. The strong-side winger stays in his yellow box (wing back steps up, holding mid stays) or enters (wing back marks him, att mid closes the full back, holding mid steps in on No.6).', 'Whites may not pass back to the GK or anyone in the box to set up a switch.', NULL, 'Focus is the press, not transition: lost counters restart from the white GK. Mark receivers aggressively and double when possible; stay compact with synchronised moves.', '8+GK v 7', 16, 17, 'half pitch; 8 x 8 and 4 x 4 yard boxes', NULL, NULL, NULL, false, true, true, NULL, 390),
  ('Compact passive defence vs 3-4-3 11v11', 'conditioned_game', 'opposed', 'out_of_possession', 176, 177, 'Session (2 Practices): Practice 1', 'Conte (Juventus)', 'Defend passively in a middle-third zone against a 3-4-3 in an 11v11.', '2/3 of a full pitch with goals and keepers at both ends; a blue zone 35 yards x full width holds all black outfield players. White GK passes to one of 3 defenders outside the zone.', 'Blacks stay compact and wait for whites to come into the blue zone. Whites score by beating the GK, completing a set number of passes in the zone (by level) or keeping it 4-5 seconds there. On a regain blacks have 6-8 seconds to score in the far goal; lost counter restarts from the white GK.', NULL, NULL, 'Position to the ball and block vertical and diagonal lanes to the forwards; move in sync to keep short distances and pass on markers; compact first, then react. Adaptable to any formation.', '11v11', 22, 22, '2/3 pitch; blue zone 35 yards x full width', 32.0, NULL, NULL, true, true, true, NULL, 400),
  ('Collective press stop switch vs 3-4-3 11v11', 'conditioned_game', 'opposed', 'out_of_possession', 178, 179, 'Session (2 Practices): Practice 2 (progression)', 'Conte (Juventus)', 'Press a 3-4-3 as a team in an 11v11 and stop switches of play.', '2/3 of a full pitch with goals at both ends, split down the middle to show the strong side; 4 blue 8 x 8 yard boxes near the touchlines as switch targets.', 'From the GK, whites score by beating the GK, 5 straight passes, or a switch received in a far blue box. Blacks press to stop all three, win it and score within 6-8 seconds; lost counter restarts from the white GK.', 'Whites may not pass back to the GK or into the penalty area to switch to the weak side.', NULL, 'Aggressive marking of receivers; double mark with good communication; stay compact and cover each other in a chain reaction. Adaptable to any formation.', '11v11', 22, 22, '2/3 pitch; 8 x 8 yard boxes', NULL, NULL, NULL, true, true, true, NULL, 410)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-defending') b;
INSERT INTO schema_migrations (filename) VALUES ('2252-exercises-book-coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-d.sql') ON CONFLICT DO NOTHING;
